import sys


def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    strings = input_data[1:]

    seen_full = set()
    seen_prefixes = set()
    seen_suffixes = set()

    for s in strings:
        # Check if s can be formed
        invalid = False
        if s in seen_full:
            invalid = True
        else:
            for j in range(1, 10):
                pref = s[:j]
                suff = s[j:]
                if pref in seen_suffixes and suff in seen_prefixes:
                    invalid = True
                    break

        if invalid:
            print(s)
            return

        # If not invalid, add its prefixes, suffixes, and full string
        seen_full.add(s)
        for j in range(1, 10):
            seen_prefixes.add(s[:j])
            seen_suffixes.add(s[10 - j :])

    print("ok")


if __name__ == "__main__":
    solve()
